mapper.select:
/* ProductMapper.findProductEntityById */
SELECT PRD_SN, USR_SN, CAT_SN, PRD_NM, PRD_CN, PRD_STATUS_CD,
       PRD_START_AMT, PRD_IBY_AMT, PRD_TRD_METHOD_CD, PRD_USE_YN,
       PRD_REG_DT, PRD_UPDT_DT, PRD_REG_ID, PRD_UPDT_ID
  FROM PRODUCT
 WHERE PRD_SN = #{prdSn}

/* ProductMapper.findActiveViewCount */
SELECT PRD_VIEW_CNT
  FROM PRODUCT
 WHERE PRD_SN = #{prdSn}
   AND PRD_USE_YN = 'Y'
   AND PRD_STATUS_CD != 'PRDC0004'

mapper.update:
/* ProductMapper.incrementViewCount */
UPDATE PRODUCT
   SET PRD_VIEW_CNT = PRD_VIEW_CNT + 1
 WHERE PRD_SN = #{prdSn}
   AND PRD_USE_YN = 'Y'

/* ProductMapper.deleteProduct */
UPDATE PRODUCT
   SET PRD_USE_YN    = 'N',
       PRD_STATUS_CD = 'PRDC0004',
       PRD_UPDT_ID   = CAST(#{usrSn} AS CHAR)
 WHERE PRD_SN = #{prdSn}
   AND USR_SN = #{usrSn}

mapper.select:
/* ProductMapper.findExpiredCancelledProductIds */
SELECT p.PRD_SN
  FROM PRODUCT p
  JOIN AUCTION a ON a.PRD_SN = p.PRD_SN
 WHERE p.PRD_USE_YN = 'Y'
   AND a.AUC_STATUS_CD = 'AUCC0005'
   AND a.AUC_UPDT_DT <= #{cutoff}
 ORDER BY a.AUC_UPDT_DT ASC
 LIMIT #{limit}

/* ProductMapper.findAuctionBidderIds */
SELECT DISTINCT b.USR_SN
  FROM BID b
  JOIN AUCTION a ON a.AUC_SN = b.AUC_SN
 WHERE a.PRD_SN = #{prdSn}

/* ProductMapper.existsBlockingAuction */
SELECT EXISTS (
    SELECT 1 FROM AUCTION
     WHERE PRD_SN = #{prdSn}
       AND AUC_STATUS_CD NOT IN ('AUCC0004', 'AUCC0005')
)

/* ProductMapper.findAuctionStatus */
SELECT AUC_STATUS_CD
  FROM AUCTION
 WHERE PRD_SN = #{prdSn}
